-- Carlos Castillo (profileID=3) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Carlos Castillo phrasings

SELECT p.argumentID, p.phrasingID, 3, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 3
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 3 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=3 AND targArgID IN (52,54,90,94,100,101,104,107,108,118,120,123,134,135,136,140,142,145,151,161,165,201,203,226,227,228,229,265,266,267,275,288,291,293,296,297,322,328,400,401,404,412,414,428,449,460,462,494,495,554,560,561,600,601,607,609,611,612,616,617,727,745,777,785,791,795,797,801,849,920,972,1045,1159,1160,1172,1177,1178,1179,1181,1229,1237,1275,1276,1278,1345,1346,1347,1410,1562,1591,1597,1602);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 3
SET pe.active = o.acceptance
WHERE pe.profileID = 3;

SELECT 'Done: endorsements for profileID=3' AS status;